	if err != nil {
		if err == sql.ErrNoRows {
			// Record not found - this is not an error, just return false
			return false
		}
		// Actual database error
		fmt.Printf("Error: Failed to get Date_Compr_Register: %v\n", err)
		return false
	}

	// Populate fields
	t.No = noVal
